#include <bits/stdc++.h>
using namespace std;

char s[7][15] = {
    "monday", "tuesday", "wednesday", "thursday",
    "friday", "saturday", "sunday"
};

int main() {
    char a[2][15];
    int b[2];

    cin >> a[0] >> a[1];

    for (int j = 0; j < 2; ++j) {
        for (int i = 0; i < 7; ++i) {
            if (strcmp(a[j], s[i]) == 0) {
                b[j] = i + 1;
                break;
            }
        }
    }

    if (b[0] == b[1] ||
        (b[0] + 2) % 7 == b[1] % 7 ||
        (b[0] + 3) % 7 == b[1] % 7)
        cout << "YES\n";
    else
        cout << "NO\n";

    return 0;
}

